// ============================================================================
// VOICE RULES: the node for what callers HEAR and what the agent is told. DATA ONLY (no logic).
// Edit the values between the EDIT lines. Every request is checked against it, and a mistake
// gives a clear 500 (voice_misconfigured, lines start "Rules:") before any audio is processed.
// What you cannot change here, on purpose: audio checks, the confidence / silence / language
// judgement, "only real answers are saved to the conversation", the TTS audio checks, and that
// failures stay honest (a degraded reply is still marked degraded).
// ============================================================================
// ---- EDIT FROM HERE ---------------------------------------------------------
const rules = {
  // The fixed sentences callers hear, per language (2-letter code of the language the caller spoke).
  // Anything you leave out uses the CONFIG.MSG_* text. Keys: stt_failed, clarify, unsupported_language, agent_failed
  messages: {
    // clarify: { es: 'Perdón, no le entendí. ¿Puede repetirlo?', fr: 'Désolé, pouvez-vous répéter ?' },
  },

  // Fixed answers for phrases you never want to leave to the agent (no agent call, nothing saved).
  // The first shortcut whose match_any text appears in what the caller said (ignoring case) wins.
  // reply: text, or { default: 'text', es: 'texto' } chosen by the caller's language.
  shortcuts: [
    // { name: 'handoff', match_any: ['speak to a human', 'operator'], reply: 'Connecting you to a person now.' },
  ],

  // How to PRONOUNCE things: applied only to the text sent to text-to-speech, never to the written reply.
  speech_replacements: [
    // { from: 'Dr.', to: 'Doctor' },
  ],

  // Fixed facts sent to the agent with every turn as "context" (text, numbers or true/false).
  agent_context: {
    // channel: 'phone', brand: 'Acme',
  },
};
// ---- STOP EDITING HERE ------------------------------------------------------
const pick = (o, k, d) => (o && o[k] !== undefined && o[k] !== null ? o[k] : d);
const norm = { messages: pick(rules, 'messages', {}), shortcuts: pick(rules, 'shortcuts', []), speech_replacements: pick(rules, 'speech_replacements', []), agent_context: pick(rules, 'agent_context', {}),
  _is_obj: rules !== null && typeof rules === 'object' && !Array.isArray(rules), _raw_keys: Object.keys(rules || {}) };
return [{ json: { ...$input.first().json, rules: norm } }];

const C = $('CONFIG').first().json;
const req = $('Voice Intake Webhook').first().json;
const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const reject = (status, error, details) => [{ json: { ok: false, http_status: status, response_body: { error, ...(details ? { details } : {}) } } }];

if (C.VOICE_AUTH_TOKEN && (req.headers || {})['x-voice-token'] !== C.VOICE_AUTH_TOKEN) return reject(401, 'unauthorized');

// ---- CONFIG sanity
const bad = [];
for (const k of ['SESSION_API_URL', 'STT_API_URL', 'AGENT_API_URL', 'TTS_API_URL']) if (!/^https?:\/\//.test(C[k] || '')) bad.push(`CONFIG.${k} must start with http:// or https://`);
if (C.QA_ARCHIVE_API_URL && !/^https?:\/\//.test(C.QA_ARCHIVE_API_URL)) bad.push('CONFIG.QA_ARCHIVE_API_URL must be blank or start with http(s)://');
for (const k of ['SERVICE_HEADERS_JSON', 'STT_HEADERS_JSON', 'AGENT_HEADERS_JSON', 'TTS_HEADERS_JSON']) { try { if (!isObj(JSON.parse(C[k] || '{}'))) throw 0; } catch (e) { bad.push(`CONFIG.${k} must be a JSON object`); } }
const arr = (k) => { try { const a = JSON.parse(C[k]); if (!Array.isArray(a) || !a.length) throw 0; return a; } catch (e) { bad.push(`CONFIG.${k} must be a non-empty JSON array`); return []; } };
const langs = arr('SUPPORTED_LANGUAGES_JSON'); const formats = arr('ALLOWED_FORMATS_JSON');
if (formats.some((f) => !['wav', 'mp3', 'ogg', 'webm'].includes(f))) bad.push('CONFIG.ALLOWED_FORMATS_JSON may only contain wav, mp3, ogg, webm');
if (langs.length && !langs.includes(C.DEFAULT_LANGUAGE)) bad.push('CONFIG.DEFAULT_LANGUAGE must be one of SUPPORTED_LANGUAGES_JSON');
try { JSON.parse(C.NON_SPEECH_PATTERNS_JSON).forEach((p) => new RegExp(p, 'i')); } catch (e) { bad.push('CONFIG.NON_SPEECH_PATTERNS_JSON must be a JSON array of valid regular expressions'); }
const num = (k) => Number(C[k]);
for (const k of ['MAX_AUDIO_BYTES', 'MAX_DURATION_SECONDS', 'MAX_HISTORY_TURNS', 'TTS_MAX_CHARS', 'MAX_TTS_AUDIO_BYTES', 'REQUEST_TIMEOUT_MS', 'STT_TIMEOUT_MS', 'AGENT_TIMEOUT_MS', 'TTS_TIMEOUT_MS']) if (!(num(k) > 0)) bad.push(`CONFIG.${k} must be a number > 0`);
if (!(num('MIN_DURATION_SECONDS') >= 0 && num('MIN_DURATION_SECONDS') < num('MAX_DURATION_SECONDS'))) bad.push('CONFIG.MIN_DURATION_SECONDS must be >= 0 and below MAX_DURATION_SECONDS');
if (!(num('NO_SPEECH_THRESHOLD') > 0 && num('NO_SPEECH_THRESHOLD') <= 1)) bad.push('CONFIG.NO_SPEECH_THRESHOLD must be between 0 and 1');
if (!(num('MIN_CONFIDENCE_LOGPROB') <= 0)) bad.push('CONFIG.MIN_CONFIDENCE_LOGPROB must be 0 or negative (average log-probability, e.g. -1.0)');
if (!(Number.isInteger(num('DEGRADED_STATUS_CODE')) && num('DEGRADED_STATUS_CODE') >= 200 && num('DEGRADED_STATUS_CODE') <= 599)) bad.push('CONFIG.DEGRADED_STATUS_CODE must be an HTTP status between 200 and 599');
for (const k of ['MSG_STT_FAILED', 'MSG_CLARIFY', 'MSG_UNSUPPORTED_LANGUAGE', 'MSG_AGENT_FAILED']) if (!String(C[k] || '').trim()) bad.push(`CONFIG.${k} must not be empty (it is what the caller hears)`);
// ---- the Voice Rules node
{
  const R = $('Voice Rules').first().json.rules;
  const rb = (m) => bad.push('Rules: ' + m);
  const str = (v, min, max) => typeof v === 'string' && v.length >= min && v.length <= max;
  const LANG = /^[a-z]{2}$/;
  const langMap = (v, allowDefault) => isObj(v) && Object.keys(v).length >= 1 && Object.keys(v).length <= 30 && Object.entries(v).every(([k, t]) => (LANG.test(k) || (allowDefault && k === 'default')) && str(t, 1, 500));
  if (!R._is_obj) rb('rules must be an object');
  else {
    for (const k of R._raw_keys) if (!['messages', 'shortcuts', 'speech_replacements', 'agent_context'].includes(k)) rb(`${k} is not a known setting (messages, shortcuts, speech_replacements, agent_context)`);
    if (!isObj(R.messages)) rb('messages must be an object');
    else for (const [k, v] of Object.entries(R.messages)) {
      if (!['stt_failed', 'clarify', 'unsupported_language', 'agent_failed'].includes(k)) rb(`messages.${k} is not a known message (stt_failed, clarify, unsupported_language, agent_failed)`);
      else if (!langMap(v)) rb(`messages.${k} must be an object of 2-letter language code -> text (1 to 500 characters)`);
    }
    if (!Array.isArray(R.shortcuts) || R.shortcuts.length > 20) rb('shortcuts must be a list of at most 20 shortcuts');
    else {
      const names = new Set();
      R.shortcuts.forEach((s, i) => {
        const w = `shortcuts[${i}]`;
        if (!isObj(s)) { rb(`${w} must be an object`); return; }
        for (const k of Object.keys(s)) if (!['name', 'match_any', 'reply'].includes(k)) rb(`${w}.${k} is not a known setting (name, match_any, reply)`);
        if (typeof s.name !== 'string' || !/^[a-z][a-z0-9_]{0,39}$/.test(s.name)) rb(`${w}.name must be lower-case letters, digits and _ (1 to 40 characters)`);
        else if (names.has(s.name)) rb(`${w}.name "${s.name}" is used twice`); else names.add(s.name);
        if (!(Array.isArray(s.match_any) && s.match_any.length >= 1 && s.match_any.length <= 30 && s.match_any.every((x) => str(x, 2, 100)))) rb(`${w}.match_any must be a list of 1 to 30 phrases of 2 to 100 characters`);
        if (typeof s.reply === 'string') { if (!str(s.reply, 1, 500)) rb(`${w}.reply must be 1 to 500 characters`); }
        else if (!(langMap(s.reply, true) && typeof s.reply.default === 'string')) rb(`${w}.reply must be text, or an object of language code -> text that includes "default"`);
      });
    }
    if (!Array.isArray(R.speech_replacements) || R.speech_replacements.length > 50 || !R.speech_replacements.every((x) => isObj(x) && Object.keys(x).every((k) => ['from', 'to'].includes(k)) && str(x.from, 1, 50) && str(x.to, 0, 100))) rb('speech_replacements must be a list of at most 50 entries { from: 1 to 50 characters, to: up to 100 characters }');
    if (!isObj(R.agent_context) || Object.keys(R.agent_context).length > 20 || !Object.entries(R.agent_context).every(([k, v]) => /^[a-z][a-z0-9_]{0,39}$/.test(k) && (typeof v === 'boolean' || (typeof v === 'number' && Number.isFinite(v)) || str(v, 0, 200)))) rb('agent_context must be an object of at most 20 entries: lower-case name -> text (up to 200 characters), number or true/false');
  }
}
if (bad.length) return reject(500, 'voice_misconfigured', bad);

// ---- request shape
if (!isObj(req.body)) return reject(400, 'validation_failed', ['body must be a JSON object']);
const b = req.body;
const errors = [];
const fmt = typeof b.audio_format === 'string' ? b.audio_format.trim().toLowerCase() : '';
if (!formats.includes(fmt)) errors.push(`audio_format must be one of: ${formats.join(', ')}`);

let b64 = typeof b.audio_base64 === 'string' ? b.audio_base64.replace(/^data:[^;,]*;base64,/i, '').replace(/\s+/g, '') : '';
let buf = null;
if (!b64) errors.push('audio_base64 is required (base64-encoded audio)');
else if (!/^[A-Za-z0-9+/]+={0,2}$/.test(b64) || b64.length % 4 !== 0) errors.push('audio_base64 is not valid base64');
else {
  buf = Buffer.from(b64, 'base64');
  if (buf.length < 64) errors.push('audio is too small to contain speech');
  else if (buf.length > num('MAX_AUDIO_BYTES')) errors.push(`audio exceeds the ${num('MAX_AUDIO_BYTES')} byte limit`);
  else if (C.CHECK_AUDIO_SIGNATURE === true && formats.includes(fmt)) {
    const h = buf.subarray(0, 12); const s = (a, n) => h.subarray(a, a + n).toString('latin1');
    const okSig = { wav: s(0, 4) === 'RIFF' && s(8, 4) === 'WAVE', mp3: s(0, 3) === 'ID3' || (h[0] === 0xff && (h[1] & 0xe0) === 0xe0), ogg: s(0, 4) === 'OggS', webm: h[0] === 0x1a && h[1] === 0x45 && h[2] === 0xdf && h[3] === 0xa3 }[fmt];
    if (!okSig) errors.push(`the audio bytes do not look like ${fmt} (wrong or missing file signature)`);
  }
}
let duration = null;
if (b.duration_seconds !== undefined && b.duration_seconds !== null) {
  if (typeof b.duration_seconds !== 'number' || !Number.isFinite(b.duration_seconds)) errors.push('duration_seconds must be a number');
  else if (b.duration_seconds < num('MIN_DURATION_SECONDS')) errors.push(`audio is too short (< ${num('MIN_DURATION_SECONDS')}s) to contain speech`);
  else if (b.duration_seconds > num('MAX_DURATION_SECONDS')) errors.push(`audio exceeds ${num('MAX_DURATION_SECONDS')}s; split it into shorter clips`);
  else duration = b.duration_seconds;
}
const idField = (k) => { const v = b[k]; if (v === undefined || v === null || v === '') return null; if (typeof v !== 'string' || !/^[A-Za-z0-9._:-]{1,128}$/.test(v)) { errors.push(`${k} must be 1-128 characters: letters, digits and . _ : -`); return null; } return v; };
const session_id = idField('session_id'), turn_id = idField('turn_id');
if (errors.length) return reject(400, 'validation_failed', errors);

return [{ json: { ok: true, audio_b64: b64, audio_format: fmt, audio_bytes: buf.length, duration_seconds: duration, session_id, turn_id } }];

const V = $('Validate Request').first().json;
const r = $input.first().json;
const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
if (!r.error && r.statusCode === 200 && isObj(r.body) && Array.isArray(r.body.history)) {
  const history = r.body.history.filter((h) => isObj(h) && typeof h.text === 'string' && ['user', 'assistant'].includes(h.role)).map((h) => ({ role: h.role, text: h.text }));
  return [{ json: { session_id: V.session_id, history, session_status: 'existing', can_save: true } }];
}
if (!r.error && r.statusCode === 404) return [{ json: { session_id: null, history: [], session_status: 'expired', can_save: true } }];
return [{ json: { session_id: V.session_id, history: [], session_status: 'unavailable', can_save: false } }];

const V = $('Validate Request').first().json;
const mime = { wav: 'audio/wav', mp3: 'audio/mpeg', ogg: 'audio/ogg', webm: 'audio/webm' }[V.audio_format];
const binary = await this.helpers.prepareBinaryData(Buffer.from(V.audio_b64, 'base64'), 'input.' + V.audio_format, mime);
return [{ json: {}, binary: { data: binary } }];

const C = $('CONFIG').first().json;
const r = $input.first().json;
const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const out = (outcome, extra = {}) => [{ json: { outcome, transcript: '', language: null, confidence: null, no_speech_prob: null, ...extra } }];

if (r.error || !(r.statusCode >= 200 && r.statusCode < 300) || !isObj(r.body) || typeof r.body.text !== 'string') return out('stt_failed');

const transcript = r.body.text.replace(/\s+/g, ' ').trim();
const NAMES = { english: 'en', spanish: 'es', french: 'fr', german: 'de', italian: 'it', portuguese: 'pt', dutch: 'nl', japanese: 'ja', chinese: 'zh', korean: 'ko', russian: 'ru', arabic: 'ar', hindi: 'hi' };
let lang = typeof r.body.language === 'string' ? r.body.language.trim().toLowerCase() : '';
lang = NAMES[lang] || lang.split(/[-_]/)[0] || null;

const segs = Array.isArray(r.body.segments) ? r.body.segments.filter(isObj) : [];
const avg = (k) => { const v = segs.map((s) => s[k]).filter((x) => typeof x === 'number' && Number.isFinite(x)); return v.length ? v.reduce((a, b) => a + b, 0) / v.length : null; };
const confidence = avg('avg_logprob'), noSpeech = avg('no_speech_prob');
const base = { transcript, language: lang, confidence, no_speech_prob: noSpeech };

const nonSpeech = JSON.parse(C.NON_SPEECH_PATTERNS_JSON).some((p) => new RegExp(p, 'i').test(transcript));
if (!transcript || nonSpeech || (noSpeech !== null && noSpeech > Number(C.NO_SPEECH_THRESHOLD))) return out('silent', base);
// Confidence is only judged when the service reports it. An unknown confidence is NOT a bad confidence.
if (confidence !== null && confidence < Number(C.MIN_CONFIDENCE_LOGPROB)) return out('low_confidence', base);
if (lang && !JSON.parse(C.SUPPORTED_LANGUAGES_JSON).includes(lang)) return out('unsupported_language', base);
return out('proceed', base);

const C = $('CONFIG').first().json;
const T = $input.first().json;
const R = $('Voice Rules').first().json.rules;
const kind = { stt_failed: 'stt_failed', silent: 'clarify', low_confidence: 'clarify', unsupported_language: 'unsupported_language' }[T.outcome];
const custom = T.language && Object.prototype.hasOwnProperty.call(R.messages, kind) && Object.prototype.hasOwnProperty.call(R.messages[kind], T.language) ? R.messages[kind][T.language] : null;
const text = custom || { stt_failed: C.MSG_STT_FAILED, silent: C.MSG_CLARIFY, low_confidence: C.MSG_CLARIFY, unsupported_language: C.MSG_UNSUPPORTED_LANGUAGE }[T.outcome];
return [{ json: { outcome: T.outcome, transcript: T.transcript || '', response_text: text, language: custom ? T.language : C.DEFAULT_LANGUAGE, degraded: T.outcome === 'stt_failed', warnings: [], session_saved: false } }];

const C = $('CONFIG').first().json;
const R = $('Voice Rules').first().json.rules;
const T = $('Assess Transcript').first().json;
const lang = T.language && JSON.parse(C.SUPPORTED_LANGUAGES_JSON).includes(T.language) ? T.language : C.DEFAULT_LANGUAGE;
const low = T.transcript.toLowerCase();
const hit = R.shortcuts.find((s) => s.match_any.some((x) => low.includes(x.toLowerCase())));
if (!hit) return [{ json: { shortcut: false } }];
const reply = typeof hit.reply === 'string' ? hit.reply : (Object.prototype.hasOwnProperty.call(hit.reply, lang) ? hit.reply[lang] : hit.reply.default);
return [{ json: { shortcut: true, outcome: 'shortcut', shortcut_name: hit.name, transcript: T.transcript, response_text: reply, language: lang, degraded: false, warnings: [], session_saved: false } }];

const C = $('CONFIG').first().json;
const S = $('Session State').first().json;
const T = $('Assess Transcript').first().json;
const V = $('Validate Request').first().json;
const lang = T.language && JSON.parse(C.SUPPORTED_LANGUAGES_JSON).includes(T.language) ? T.language : C.DEFAULT_LANGUAGE;
return [{ json: { session_id: S.session_id, history: S.history.slice(-2 * Number(C.MAX_HISTORY_TURNS)), message: T.transcript, language: lang, turn_id: V.turn_id, ...(Object.keys($('Voice Rules').first().json.rules.agent_context).length ? { context: $('Voice Rules').first().json.rules.agent_context } : {}) } }];

const C = $('CONFIG').first().json;
const r = $input.first().json;
const T = $('Assess Transcript').first().json;
const S = $('Session State').first().json;
const reply = r.body && typeof r.body.reply === 'string' ? r.body.reply.trim() : '';
const lang = T.language && JSON.parse(C.SUPPORTED_LANGUAGES_JSON).includes(T.language) ? T.language : C.DEFAULT_LANGUAGE;
if (!r.error && r.statusCode >= 200 && r.statusCode < 300 && reply) return [{ json: { answered: true, outcome: 'answered', transcript: T.transcript, response_text: reply, language: lang, degraded: false, warnings: [] } }];
const R = $('Voice Rules').first().json.rules;
const customFail = R.messages.agent_failed && Object.prototype.hasOwnProperty.call(R.messages.agent_failed, lang) ? R.messages.agent_failed[lang] : null;
return [{ json: { answered: false, outcome: 'agent_failed', transcript: T.transcript, response_text: customFail || C.MSG_AGENT_FAILED, language: customFail ? lang : C.DEFAULT_LANGUAGE, degraded: true, warnings: [], session_saved: false } }];

const A = $('Interpret Agent').first().json;
const r = $input.first().json;
const saved = r.save !== 'skipped' && !r.error && r.statusCode >= 200 && r.statusCode < 300;
const warnings = saved ? [] : [r.save === 'skipped' ? 'session_store_unavailable' : 'session_not_saved'];
return [{ json: { ...A, warnings, session_saved: saved } }];

const C = $('CONFIG').first().json;
const U = $input.first().json;
const max = Number(C.TTS_MAX_CHARS);
let speak = U.response_text, truncated = false;
for (const r of $('Voice Rules').first().json.rules.speech_replacements) speak = speak.split(r.from).join(r.to);
if (speak.length > max) {
  let cut = speak.slice(0, max);
  const floor = Math.floor(max * 0.6);
  let at = Math.max(cut.lastIndexOf('. '), cut.lastIndexOf('! '), cut.lastIndexOf('? '));
  if (at >= floor) cut = cut.slice(0, at + 1);
  else { at = cut.lastIndexOf(' '); if (at >= floor) cut = cut.slice(0, at); }
  speak = cut.trim(); truncated = true;
}
return [{ json: { ...U, speak_text: speak, truncated_for_speech: truncated } }];

const C = $('CONFIG').first().json;
const U = $('Prepare Speech').first().json;
const V = $('Validate Request').first().json;
const S = $('Session State').first().json;
const item = $input.first();
const warnings = [...(U.warnings || [])];
let audio = null, mime = null;
if (C.TTS_ENABLED === true) {
  const bin = item.binary && item.binary.data;
  if (item.json.error || !bin) warnings.push('tts_failed');
  else {
    const buf = await this.helpers.getBinaryDataBuffer(0, 'data');     // works in every n8n binary storage mode
    if (!/^audio\//i.test(bin.mimeType || '') || !buf.length || buf.length > Number(C.MAX_TTS_AUDIO_BYTES)) warnings.push('tts_invalid_audio');
    else { audio = buf.toString('base64'); mime = bin.mimeType; }
  }
}
const body = { outcome: U.outcome, session_id: S.session_id, session_status: S.session_status, transcript: U.transcript, response_text: U.response_text, language: U.language,
  has_audio: audio !== null, response_audio_base64: audio, response_audio_mime: mime, truncated_for_speech: U.truncated_for_speech, warnings, ...(U.shortcut ? { shortcut: U.shortcut } : {}) };
return [{ json: { http_status: U.degraded ? Number(C.DEGRADED_STATUS_CODE) : 200, response_body: body,
  qa: { session_id: S.session_id, outcome: U.outcome, transcript: U.transcript, response_text: U.response_text, language: U.language, has_audio: audio !== null, warnings, created_at: new Date().toISOString() } } }];

const C = $('CONFIG').first().json;
const qa = $input.first().json.qa;
if (!C.QA_ARCHIVE_API_URL || !qa) return [];
return [{ json: qa }];
